package org.researchdock.mobile;
import org.json.*;
import java.time.*;
final class ResearchHome {
 static long epoch(String value){try{return OffsetDateTime.parse(value).toInstant().toEpochMilli();}catch(Exception e){return 0;}}
 static boolean importedToday(JSONObject d,LocalDate today){try{return OffsetDateTime.parse(d.optString("first_imported_at")).atZoneSameInstant(ZoneId.of("Asia/Shanghai")).toLocalDate().equals(today);}catch(Exception e){return false;}}
 static boolean analysisCurrent(JSONObject d){return d.optInt("revision")>0&&d.optInt("analysis_revision")==d.optInt("revision");}
 static String displayTitle(JSONObject d){String title=d.optString("display_title");return title.isEmpty()?d.optString("title"):title;}
 static String stateName(String s){switch(s){case "succeeded":return "采集成功";case "partial":return "部分内容待补全";case "failed":return "采集失败";case "interrupted":return "采集中断";case "running":return "正在采集";case "queued":return "等待采集";case "idle":return "尚未采集";default:return "状态未知";}}
 static String healthLabel(JSONObject h,String received,long now){if(h==null)return "采集状态未知 · 点击查看";long stamp=epoch(received);if(stamp==0||now-stamp>120000)return "Mac 发布器状态已过期 · 点击查看";JSONArray sources=h.optJSONArray("sources");if(sources==null||sources.length()==0)return "尚未配置采集源 · 点击查看";if(!h.optBoolean("poll_enabled"))return "自动采集已关闭 · 点击查看";long oldest=Long.MAX_VALUE;boolean running=false,partial=false;for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);String state=s.optString("status");if(state.equals("failed")||state.equals("interrupted"))return "星球采集异常 · 点击查看原因";if(state.equals("unknown"))return "采集状态未知 · 点击查看";running|=state.equals("running")||state.equals("queued");partial|=state.equals("partial");oldest=Math.min(oldest,epoch(s.optString("last_success_at")));}if(partial)return "部分主题待补全 · 点击查看";if(running)return "正在采集新资料 · 点击查看";if(oldest==0)return "尚无成功采集记录 · 点击查看";if(now-oldest>(Math.max(5,h.optInt("poll_minutes",5))+3)*60000L)return "采集更新已延迟 · 点击查看";return "采集正常 · 点击查看同步链路";}
 static boolean healthy(JSONObject h,String received,long now){return healthLabel(h,received,now).startsWith("采集正常")||healthLabel(h,received,now).startsWith("正在采集");}
 static String attachmentSummary(JSONObject d){JSONArray list=d.optJSONArray("attachments");if(list==null||list.length()==0)return "附件清单尚未取得，可查看原始来源";int pdf=0,audio=0,image=0,file=0;for(int i=0;i<list.length();i++){String t=list.optJSONObject(i).optString("type");if(t.equals("pdf"))pdf++;else if(t.equals("audio"))audio++;else if(t.equals("image"))image++;else file++;}StringBuilder s=new StringBuilder("附件 "+list.length()+" 项");if(pdf>0)s.append(" · PDF ").append(pdf);if(audio>0)s.append(" · 音频 ").append(audio);if(image>0)s.append(" · 图片 ").append(image);if(file>0)s.append(" · 文件 ").append(file);return s.toString();}
}
